INSERT OR IGNORE INTO vehicle_weapons (vehicle_slug, ordinal, name, damage, is_mega_damage, range, rate_of_fire, payload, bonus, note) VALUES
  ('ng-ex-v50-scorpion-battler', 1, 'Tail Ion Cannon (1, top)', '1D4x10 M.D. per single blast; may fire linked with the two tail lasers (see that entry)', 1, '2,000 ft (610 m)', 'One melee attack per single or linked blast', 'Effectively unlimited', NULL, 'Tail Multi-Weapon Platform. Assault and anti-armor, secondarily anti-monster and defense. The big barrel at the end of the fully jointed tail, aimed by pointing the tail any direction; flanked by a gun camera and two spotlights reaching 2,000 ft (610 m).'),
  ('ng-ex-v50-scorpion-battler', 2, 'Tail Dual Laser Cannons (2, top)', '3D6 M.D. single, 6D6 M.D. simultaneous double; 1D6x10+15 M.D. linked with the ion cannon', 1, '4,000 ft (1,219 m); a linked shot needs the target inside the ion cannon''s range', 'One melee attack per single, paired or triple linked blast', 'Effectively unlimited', NULL, 'Tail Multi-Weapon Platform. Assault and anti-personnel, secondarily anti-flyer and anti-missile. Two long, slim barrels beside the ion cannon, outranging it.'),
  ('ng-ex-v50-scorpion-battler', 3, 'Tail Mini-Missile Launch Tubes (2)', 'By missile; any mini-missile, standard armor piercing (1D4x10 M.D.) or plasma (1D6x10 M.D.), fragmentation (5D6 M.D.) against troops', 1, 'One mile (1.6 km)', 'Singly or two at once', '8 in all', '+1 to strike', 'Tail Multi-Weapon Platform. Anti-aircraft and anti-missile, secondarily anti-armor and anti-robot. Backs up the turret launcher and swats down incoming missiles and flyers.'),
  ('ng-ex-v50-scorpion-battler', 4, '(Option A) Turret Main Gun: Quad Mini-Missile Launcher', 'By missile; any mini-missile, standard half armor piercing (1D4x10 M.D.) and half plasma (1D6x10 M.D.)', 1, 'One mile (1.6 km)', 'Singly or volleys of 2 or 4', '40, ten per tube, reloading itself in full', '+1 to strike', 'Top-Mounted Weapon Turret; the standard fit. Anti-armor and anti-robot, secondarily anti-aircraft and anti-missile. Four forward-facing tubes with a 30 degree arc up and down; the turret itself turns 360 degrees and carries a forward camera.'),
  ('ng-ex-v50-scorpion-battler', 5, '(Option B) Turret Main Gun: Heavy Rail Gun', '1D6x10 M.D. per 60 round burst', 1, '4,000 ft (1,219 m)', 'One melee attack per burst', '6,000 rounds (100 bursts)', NULL, 'Top-Mounted Weapon Turret; replaces the quad launcher. Assault and anti-personnel, secondarily defense. Forward-facing with a 30 degree arc up, down or sideways.'),
  ('ng-ex-v50-scorpion-battler', 6, '(Option A) Turret Secondary: Medium Laser (1)', '3D6 M.D. per blast', 1, '2,000 ft (610 m)', 'One melee attack per blast', 'Effectively unlimited', NULL, 'Top-Mounted Weapon Turret; the standard fit. Defense, secondarily anti-personnel. A stubby barrel on the turret''s upper right side, 45 degrees up and down and 30 degrees side to side.'),
  ('ng-ex-v50-scorpion-battler', 7, '(Option B) Turret Secondary: Ion Blaster', '5D6 M.D. per blast', 1, '1,200 ft (366 m)', 'One melee attack per blast', 'Effectively unlimited', NULL, 'Top-Mounted Weapon Turret; replaces the laser in the same mount and arcs. Defense, secondarily anti-personnel.'),
  ('ng-ex-v50-scorpion-battler', 8, 'Right Pincer M.D. Chainsaw (1)', '1D6x10 M.D. running; 4D6 M.D. from the teeth when switched off; 3D6 M.D. full strength blow with the blunt side', 1, 'Touch; 15 ft (4.6 m) reach. The blade is 6 ft (1.8 m) on one side and 3 ft (0.9 m) on the other', 'Per melee attack; no power punch or power attack with it', 'Effectively unlimited', NULL, 'Cutting/construction and anti-fortification, secondarily assault and defense. Cuts wood, roots, earth, stone, wire, and M.D.C. concrete and metal; set in a flipper that bends 180 degrees and rotates. A modular blade with silver teeth can be swapped in against supernatural foes, its plating lasting 2D4 uses against M.D.C. armor.'),
  ('ng-ex-v50-scorpion-battler', 9, 'Left Pincer', 'Restrained punch/jab 1D6 M.D.; full strength punch, tear or crush 3D6+3 M.D.; power punch 1D6x10+6 M.D.; power punch impalement 1D6x10+12 M.D.; trip no damage (see description)', 1, 'Touch; 15 ft (4.6 m) reach', 'Per melee attack; a power punch or trip counts as two', NULL, NULL, 'Construction and cargo hauling, secondarily anti-fortification and combat. Damage includes Robot P.S. Grabs, lifts, carries, digs with its big upper claw, pulls down walls, uproots trees and shoves stalled vehicles; its pointed claw impales. Both pincers can strike mid-body, legs or feet of giant foes but seldom reach the head of one taller than 12 ft (3.6 m). Printed as Left Pincer (2), though there is one.'),
  ('ng-se48-sunfire', 1, 'Solar-Powered Laser Cannon', '1D4x10 M.D.', 1, '3,000 ft (914 m)', 'One melee attack/action per blast', '160 blasts from a fully charged solar battery pack, each blast taking an hour of direct sun to recharge; a switch ties it to the fuel cell for effectively unlimited fire until that runs dry', NULL, 'Anti-armor, secondarily anti-aircraft. The right-shoulder Nova laser, wired to the solar array, which it normally drinks most of.'),
  ('ng-se48-sunfire', 2, 'NG-VBR048 Variable Bore Rail Gun', '6D6 M.D. per 40 round burst; 1D4 M.D. per round', 1, '4,000 ft (1,219 m); half for S.D.C. ammunition and strangely shaped alien rounds', 'One melee attack per shot or burst', '4,000 round drum (100 bursts)', NULL, 'Anti-personnel and anti-monster, secondarily defense and anti-aircraft. Mounted behind the head; adapts to nearly any rail gun round, Earth, alien or unknown, and S.D.C. machine-gun ammunition, but nothing with a fuse or moving parts (grenades, mini-missiles, explosive shells).'),
  ('ng-se48-sunfire', 3, 'NG-M009 Mini-Missile Pod', 'By missile; usually plasma (1D6x10 M.D.) or A.P./Heat (1D4x10 M.D.), any type usable', 1, 'One mile (1.6 km)', 'Singly or volleys of 2 or 4', '18, nine per shoulder', NULL, 'Anti-aircraft and anti-missile, secondarily assault and defense. A launcher in each shoulder under a lid that pops open to fire.'),
  ('ng-se48-sunfire', 4, 'NG-RHD-48 Holographic Decoys (4)', 'None', 0, 'Image within 300 ft (91.4 m) of its projector', NULL, 'Four, each set out by hand; an hour of image per charge, recharged at a station inside the robot', NULL, 'Intimidation and deception. Toaster-sized projectors throwing a 3D image of a Sunfire, still or moving (walking, aiming, even firing the laser), most convincing still and seen from afar, to make watchers think more Sunfires are on guard. Radar, motion detectors, magnetometers and thermal imaging miss them and infrared and ultraviolet optics see through them; useless under water. 6 M.D.C. each; 15,000 credits each.'),
  ('ng-v10-super-labor-original', 1, 'Laser-Claw Hand (1)', 'Four settings: 1D6, 2D6, 4D6 or 6D6 M.D.', 1, '2,000 ft (610 m); 4,000 ft (1,219 m) with an 80,000 credit long barrel, which disables the claw and drops the 6D6 setting', 'One blast at a time, each one melee action/attack at any setting', 'Effectively unlimited', NULL, 'Labor/mining, secondarily cutting and welding. A heavy laser in the left arm for cutting rock, metal, debris and M.D.C. material; the claw''s own blows are in the hand to hand list.'),
  ('ng-v10-super-labor-original', 2, '(Optional) Robot Rail Gun', 'By the rail gun fitted: a giant-sized NG-202, a TX-500 or another large rail gun', 1, 'By the gun', 'By the gun', 'By the gun; a separate power pack on the back, or tapped into the robot''s nuclear supply', NULL, 'Stowed on a hip or back mount, behind the right shoulder, or carried. Costs the gun plus 6,000 credits to hook up; tapping the robot''s own power is delicate and costs 50,000 credits.'),
  ('ng-v10-super-labor-original', 3, '(Optional) Concealed Particle Beam', '6D6+6 M.D.', 1, '1,600 ft (488 m)', 'One melee attack/action per blast', 'Effectively unlimited', NULL, 'Assault, secondarily defense. Hidden in a leg and run off the nuclear power plant; this or the plasma rod. 200,000 credits fitted.'),
  ('ng-v10-super-labor-original', 4, '(Optional) Concealed Plasma Rod', '5D6 M.D.', 1, '2,000 ft (610 m)', 'One melee attack/action per blast', 'Effectively unlimited', NULL, 'Assault, secondarily defense. Hidden in a leg and run off the nuclear power plant; this or the particle beam. 200,000 credits fitted.'),
  ('ng-8000-super-max', 1, '(Option A) NG-1001 Robot Rail Rifle', '1D6x10 M.D. per 20 round burst; 1D4 M.D. per round', 1, '4,000 ft (1,219 m); half that with silver and other anti-monster rounds', 'One melee attack/action per burst', '920 rounds (46 bursts) per detachable drum; spares ride on the leg hardpoints, and a spent drum ejects and a fresh one cycles in within 15 seconds (one melee)', NULL, 'Robot Handheld Rifle; assault. Sold separately (Rifts Merc Ops p.95) but standard with the Super Max, which was designed around it. Its own power supply, so no exposed power cables.'),
  ('ng-8000-super-max', 2, '(Option B) NG-P8011 Robot Particle Beam Rifle', '1D4x10 M.D. per blast', 1, '1,400 ft (427 m)', 'Single shot only; one melee attack per blast', '8 shots per standard E-Clip; a bag (30 S.D.C.) or ammo box (15 M.D.C.) of up to eight spare clips often rides on a hardpoint', NULL, 'Robot Handheld Rifle; assault. NG''s first new particle beam in years, built for the Super Max; cyborgs and heavy power armor can use it two-handed at -2 to strike. The rifle has 90 M.D.C.; at 30 or less, roll percentile: 01-50 it smokes and quits, 51-75 it catches fire (1D6 M.D. to the hand) and burns to slag, 76-00 it explodes, doing 1D6x10 M.D. to the hand and to anything else within 4 ft (1.2 m). NG never permits wiring it to the robot''s power: a failure would then damage the power supply, burn out the sensors and do 2D6x10 M.D. to the main body.'),
  ('ng-8000-super-max', 3, '(Option A) NG-M48 Forearm Mini-Missile Launcher', 'By missile; usually plasma (1D6x10 M.D.) or A.P./Heat (1D4x10+5 M.D.), any type usable', 1, 'One mile (1.6 km)', 'Singly or two per arm at once', '8, four per arm (two per tube)', '-1 to strike while the arm holds the NG-1001', 'Forearm Weapons, the factory standard on both arms. Assault and anti-armor, secondarily anti-missile and defense. The missile exhaust has a 01-50% chance to damage the rifle''s targeting system, so pilots stow the rifle or switch hands first. Each forearm takes one modular weapon, alike or different; a swap costs 15,000 credits per arm plus the new weapon and ammunition. 50,000 credits per launcher plus 6,000 per missile.'),
  ('ng-8000-super-max', 4, '(Option B) Forearm Laser', '3D6 M.D. per blast', 1, '2,000 ft (610 m)', 'One melee attack per blast', 'Effectively unlimited', NULL, 'Forearm Weapons. Assault and anti-personnel, secondarily defense. A low-profile point-and-shoot gun. 40,000 credits each. Its rate of fire is printed cut short.'),
  ('ng-8000-super-max', 5, '(Option C) Forearm Plasma Ejector', '4D6 M.D. per blast', 1, '1,200 ft (366 m)', 'One melee attack per blast', 'Effectively unlimited', NULL, 'Forearm Weapons. Assault and anti-personnel, secondarily defense. A low-profile point-and-shoot gun. 52,000 credits each. Its rate of fire is printed cut short.'),
  ('ng-8000-super-max', 6, '(Option D) Forearm Ion Blaster', '3D6 M.D. single, 6D6 M.D. simultaneous dual blast at one target', 1, '1,200 ft (366 m)', 'One melee attack per single or double blast', 'Effectively unlimited', NULL, 'Forearm Weapons. Anti-personnel, secondarily defense. A double-barreled short-range blaster. 65,000 credits each.'),
  ('ng-8000-super-max', 7, '(Option E) Forearm Particle Beam Blaster', '6D6+6 M.D. per blast', 1, '1,000 ft (305 m)', 'One melee attack per blast', '8 blasts per E-Clip; never wired to the robot''s power', NULL, 'Forearm Weapons. Assault and anti-personnel, secondarily defense. A low-profile point-and-shoot gun. 70,000 credits each.'),
  ('ng-8000-super-max', 8, 'NG-C44 Shoulder-Mounted Short-Range Missile Pod (1, right shoulder)', 'By missile; standard armor piercing (2D6x10 M.D., 5 ft/1.5 m radius) or plasma (2D6x10 M.D., 15 ft/4.6 m radius)', 1, 'Five miles (8 km)', 'Singly or two at once', '3 short-range missiles', NULL, 'Assault, secondarily anti-aircraft. For heavier fights. NG fits no substitute, though a capable Operator can trade it for an NG-M99. 75,000 credits for the launcher; short-range missiles 2,000-4,500 credits each by type (Rifts Ultimate Edition p.256).'),
  ('ng-8000-super-max', 9, 'NG-M99 Shoulder Mini-Missile Launcher (1, left shoulder)', 'By missile; usually plasma (1D6x10 M.D.) or A.P./Heat (1D4x10+5 M.D.), any type usable', 1, 'One mile (1.6 km)', 'Singly or volleys of 2, 4 or 6', '12', NULL, 'Anti-aircraft, anti-armor and assault, secondarily anti-missile and defense. Part of the robot''s combined missile and grenade system, built to match the Ulti-Max''s firepower. NG fits no substitute, though a capable Operator can trade it for an NG-C44. 65,000 credits for the launcher; mini-missiles 1,200-2,500 credits each by type (Rifts Ultimate Edition p.257).'),
  ('ng-8000-super-max', 10, 'NG-G88 Beehive Grenade Launchers (2)', 'By grenade; a typical load is 12 smoke and 12 HEX (both as the Grizzly), 30 fragmentation (2D6 M.D., 20 ft/6.1 m radius) and 30 explosive (4D6 M.D., 6 ft/1.8 m radius)', 1, '1,200 ft (366 m)', 'Singly or volleys of 2, 4, 6 or 8; any volley is one melee attack', '88, 44 per tower', NULL, 'Anti-personnel and anti-monster, secondarily anti-fortification and assault. A new, still somewhat experimental design standing in for a mass of mini-missiles: short ranged, but a crushing barrage against troops, vehicles, robots, monsters and fortifications. Each slot in a tower holds one grenade, and only half the slits are launch slots, the rest vents; the towers turn 360 degrees to fire any direction. Standard issue, no substitutes.');

-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 4 machines are in' AS assertion, count(*) AS got, 4 AS want
  FROM vehicles WHERE slug IN ('ng-ex-v50-scorpion-battler', 'ng-se48-sunfire', 'ng-v10-super-labor-original', 'ng-8000-super-max');
SELECT 'their 61 locations are in' AS assertion, count(*) AS got, 61 AS want
  FROM vehicle_locations WHERE vehicle_slug IN ('ng-ex-v50-scorpion-battler', 'ng-se48-sunfire', 'ng-v10-super-labor-original', 'ng-8000-super-max');
SELECT 'their 27 weapon entries are in' AS assertion, count(*) AS got, 27 AS want
  FROM vehicle_weapons WHERE vehicle_slug IN ('ng-ex-v50-scorpion-battler', 'ng-se48-sunfire', 'ng-v10-super-labor-original', 'ng-8000-super-max');
SELECT 'each main body location equals mdc_main_body' AS assertion, count(*) AS got, 0 AS want
  FROM vehicles v JOIN vehicle_locations l ON l.vehicle_slug = v.slug AND l.location = 'Main Body'
  WHERE v.slug IN ('ng-ex-v50-scorpion-battler', 'ng-se48-sunfire', 'ng-v10-super-labor-original', 'ng-8000-super-max') AND l.mdc IS NOT NULL AND v.mdc_main_body IS NOT NULL AND l.mdc <> v.mdc_main_body;

-- Records this run. See db/migrations/024-data-script-runs.sql.
INSERT INTO data_script_runs (filename) VALUES ('~290-northern-gun-1-robots-f.sql');
